import type {
  HyperspeedCurve,
  HyperspeedPalette,
  HyperspeedProps,
  HyperspeedSettings,
  HyperspeedTheme,
  HyperspeedVec3,
} from './types';

export const TRAVEL = 400;
export const MAX_CARS = 160;
export const MAX_POLES = 80;
export const MAX_DUST = 1500;
export const MAX_COLORS = 8;

export const CURVES: HyperspeedCurve[] = [
  'straight',
  'gentle',
  'winding',
  'hills',
  'racing',
  'deep',
];

export const THEMES: Record<HyperspeedTheme, HyperspeedPalette> = {
  dark: {
    background: 'transparent',
    road: '#08080a',
    lines: '#25252d',
    tail: ['#d856bf', '#6750a2', '#c247ac'],
    head: ['#03b3c3', '#0e5ea5', '#324555'],
    poles: ['#03b3c3'],
    dust: '#ffffff',
  },
  light: {
    background: 'transparent',
    road: '#efeff2',
    lines: '#d0d0d7',
    tail: ['#d856bf', '#6750a2', '#c247ac'],
    head: ['#03b3c3', '#0e5ea5', '#324555'],
    poles: ['#03b3c3'],
    dust: '#18181b',
  },
};

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

export function resolveSettings(props: HyperspeedProps): HyperspeedSettings {
  const theme = props.theme ?? 'dark';
  const palette = THEMES[theme] ?? THEMES.dark;
  const curve = props.curve ?? 'winding';
  return {
    light: theme === 'light',
    curve: CURVES.includes(curve) ? curve : 'winding',
    curvature: Math.max(0, props.curvature ?? 1),
    speed: Math.max(0, props.speed ?? 1),
    boost: Math.max(1, props.boost ?? 3),
    fov: clamp(props.fov ?? 90, 20, 170),
    boostFov: clamp(props.boostFov ?? 130, 20, 170),
    lanes: Math.max(1, Math.round(props.lanes ?? 3)),
    roadWidth: Math.max(1, props.roadWidth ?? 10),
    medianWidth: Math.max(0, props.medianWidth ?? 2),
    density: clamp(Math.round(props.density ?? 40), 0, MAX_CARS),
    trailLength: Math.max(0.05, props.trailLength ?? 1),
    lightSize: Math.max(0.1, props.lightSize ?? 1),
    poles: clamp(Math.round(props.poles ?? 20), 0, MAX_POLES),
    poleHeight: Math.max(0.1, props.poleHeight ?? 1),
    dust: clamp(Math.round(props.dust ?? 100), 0, MAX_DUST),
    glow: Math.max(0, props.glow ?? 0.6),
    reflections: Math.max(0, props.reflections ?? 0.5),
    steer: Math.max(0, props.steer ?? 0.35),
    tailColors: props.tailColors?.length ? props.tailColors : palette.tail,
    headColors: props.headColors?.length ? props.headColors : palette.head,
    poleColors: props.poleColors?.length ? props.poleColors : palette.poles,
    roadColor: props.roadColor || palette.road,
    roadOpacity: clamp(props.roadOpacity ?? 0.1, 0, 1),
    lineColor: props.lineColor || palette.lines,
    background: props.background || palette.background,
    dustColor: palette.dust,
    interactive: props.interactive ?? true,
    boosting: props.boosting ?? false,
  };
}

const nsin = (value: number) => Math.sin(value) * 0.5 + 0.5;
const windX = (q: number, t: number) =>
  Math.cos(Math.PI * q * 4 + t) * 25 +
  Math.cos(Math.PI * q * 8 + t * 2) ** 2 * 5;
const windY = (q: number, t: number) =>
  -nsin(Math.PI * q * 8 + t) * 10 - nsin(Math.PI * q + t / 8) ** 5 * 10;
const deepX = (q: number, t: number) => Math.sin(q * Math.PI * 4 + t) * 10;
const deepY = (q: number, t: number) =>
  Math.abs(q * 10) ** 2 + Math.sin(q * Math.PI * 8 + t) * 20;

function curveShapes(p: number, t: number): HyperspeedVec3[] {
  const { PI, cos, sin } = Math;
  return [
    [
      cos(p * PI * 5 + t) * 25 - cos(0.02 * PI * 5 + t) * 25,
      sin(p * PI * 2 + PI * 0.5 + t) * 15 -
        sin(0.02 * PI * 2 + PI * 0.5 + t) * 15,
      0,
    ],
    [windX(p, t) - windX(0.0125, t), windY(p, t) - windY(0.0125, t), 0],
    [
      cos(p * PI * 3 + t) * 30 - cos(0.02 * PI * 3 + t) * 30,
      nsin(p * PI * 6 + t) * 30 - nsin(0.02 * PI * 6 + t) * 30,
      nsin(p * PI * 10 + t) * 20 - nsin(0.02 * PI * 10 + t) * 20,
    ],
    [
      sin(p * PI * 2 + t) * 35 - sin(0.0125 * PI * 2 + t) * 35,
      sin(p * PI * 3 + t) * 10 - sin(0.0125 * PI * 3 + t) * 10,
      0,
    ],
    [deepX(p, t) - deepX(0.02, t), deepY(p, t) - deepY(0.02, t), 0],
  ];
}

/** Camera look offsets for each curve shape, matched to the road bend. */
export function lookShapes(t: number, curvature: number): HyperspeedVec3[] {
  const p = 0.025;
  const shapes = curveShapes(p, t);
  const gentle = shapes[0]!;
  const hills = shapes[2]!;
  const racing = shapes[3]!;
  return [
    [gentle[0] * curvature * 2, gentle[1] * curvature * 0.4, -3],
    [
      (windX(p, t) - windX(p + 0.007, t)) * curvature * -2,
      (windY(p, t) - windY(p + 0.007, t)) * curvature * -5,
      -10,
    ],
    [
      hills[0] * curvature * 2,
      hills[1] * curvature * 2,
      hills[2] * curvature * 2 - 5,
    ],
    [racing[0] * curvature, racing[1] * curvature, -5],
    [
      (deepX(p, t) - deepX(p + 0.01, t)) * curvature * -2,
      (deepY(p, t) - deepY(p + 0.01, t)) * curvature * -4,
      -10,
    ],
  ];
}

import * as THREE from 'three';
import type { IUniform, ShaderMaterialParameters } from 'three';
import {
  CURVES,
  MAX_CARS,
  MAX_COLORS,
  MAX_DUST,
  MAX_POLES,
  TRAVEL,
  lookShapes,
} from './hyperspeed-config';
import {
  BLOOM_FRAGMENT,
  DOWN_FRAGMENT,
  DUST_FRAGMENT,
  DUST_VERTEX,
  POLE_FRAGMENT,
  POLE_VERTEX,
  QUAD_VERTEX,
  ROAD_FRAGMENT,
  ROAD_VERTEX,
  STREAK_FRAGMENT,
  STREAK_VERTEX,
  UP_FRAGMENT,
} from './hyperspeed-shaders';
import type {
  HyperspeedEngine,
  HyperspeedEngineOptions,
  HyperspeedSettings,
  HyperspeedVec3,
} from './types';

let colorContext: CanvasRenderingContext2D | null = null;

function toRgb(color: string): HyperspeedVec3 {
  colorContext =
    colorContext ?? document.createElement('canvas').getContext('2d');
  if (!colorContext) return [1, 1, 1];
  colorContext.fillStyle = '#000000';
  colorContext.fillStyle = color;
  const value = String(colorContext.fillStyle);
  if (value.startsWith('#')) {
    const hex = Number.parseInt(value.slice(1, 7), 16);
    return [
      ((hex >> 16) & 255) / 255,
      ((hex >> 8) & 255) / 255,
      (hex & 255) / 255,
    ];
  }
  const parts = value.match(/[\d.]+/g)?.map(Number) ?? [0, 0, 0];
  return [(parts[0] ?? 0) / 255, (parts[1] ?? 0) / 255, (parts[2] ?? 0) / 255];
}

function fillPalette(
  uniform: IUniform<THREE.Vector3[]>,
  count: IUniform<number>,
  colors: string[],
) {
  const list = colors.length ? colors : ['#ffffff'];
  for (let i = 0; i < MAX_COLORS; i++) {
    uniform.value[i]!.fromArray(toRgb(list[i % list.length]!));
  }
  count.value = Math.min(list.length, MAX_COLORS);
}

function instanced(source: THREE.BufferGeometry) {
  const geometry = new THREE.InstancedBufferGeometry();
  geometry.setIndex(source.index);
  for (const [name, attribute] of Object.entries(source.attributes)) {
    geometry.setAttribute(name, attribute);
  }
  return geometry;
}

const swatches = (): IUniform<THREE.Vector3[]> => ({
  value: Array.from({ length: MAX_COLORS }, () => new THREE.Vector3(1, 1, 1)),
});

/**
 * Builds the highway scene inside `container` and runs its render loop.
 * Settings are read every frame, so prop changes apply live.
 */
export function createHyperspeedEngine(
  container: HTMLElement,
  { getSettings, reducedMotion }: HyperspeedEngineOptions,
): HyperspeedEngine {
  const renderer = new THREE.WebGLRenderer({
    antialias: true,
    alpha: true,
    powerPreference: 'high-performance',
  });
  renderer.outputColorSpace = THREE.LinearSRGBColorSpace;
  renderer.autoClear = false;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.domElement.setAttribute('aria-hidden', 'true');
  container.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(getSettings().fov, 1, 0.1, 10000);
  camera.position.set(0, 8, -5);

  const shared = {
    uTime: { value: 0 },
    uCurvature: { value: 1 },
    uCurveA: { value: new THREE.Vector4() },
    uCurveB: { value: 0 },
    uFogNear: { value: TRAVEL * 0.22 },
    uFogFar: { value: TRAVEL * 0.95 },
    uTravel: { value: TRAVEL },
    uStretch: { value: 0 },
    uPixel: { value: 0.001 },
  };
  const disposables: { dispose: () => void }[] = [];
  const effectMaterials: THREE.ShaderMaterial[] = [];

  const material = (
    vertexShader: string,
    fragmentShader: string,
    uniforms: Record<string, IUniform>,
    options: ShaderMaterialParameters = {},
  ) => {
    const created = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: { ...shared, ...uniforms },
      transparent: true,
      depthWrite: false,
      ...options,
    });
    disposables.push(created);
    return created;
  };

  const roadGeometry = new THREE.PlaneGeometry(1, TRAVEL, 1, 220);
  roadGeometry.rotateX(-Math.PI / 2);
  roadGeometry.translate(0, 0, -TRAVEL / 2);
  disposables.push(roadGeometry);
  const roadUniforms = {
    uWidth: { value: 1 },
    uRoadColor: { value: new THREE.Vector3() },
    uLineColor: { value: new THREE.Vector3() },
    uBackground: { value: new THREE.Vector3() },
    uRoadWidth: { value: 10 },
    uMedian: { value: 2 },
    uLanes: { value: 3 },
    uTransparent: { value: 0 },
    uOpacity: { value: 1 },
  };
  const roadMaterial = material(ROAD_VERTEX, ROAD_FRAGMENT, roadUniforms, {
    transparent: true,
    depthWrite: true,
  });
  const road = new THREE.Mesh(roadGeometry, roadMaterial);
  road.frustumCulled = false;
  road.renderOrder = 0;
  road.layers.enable(1);
  scene.add(road);

  const tube = new THREE.TubeGeometry(
    new THREE.LineCurve3(
      new THREE.Vector3(0, 0, 0),
      new THREE.Vector3(0, 0, -1),
    ),
    24,
    1,
    7,
    false,
  );
  disposables.push(tube);

  const glowLayer = (
    vertexShader: string,
    fragmentShader: string,
    geometry: THREE.BufferGeometry,
    uniforms: Record<string, IUniform>,
    radiusScale: number,
    sharp: number,
    mirror: number,
    order: number,
  ) => {
    const intensity = { value: 1 };
    const core = { value: 0 };
    const layerMaterial = material(
      vertexShader,
      fragmentShader,
      {
        ...uniforms,
        uRadiusScale: { value: radiusScale },
        uSharp: { value: sharp },
        uMirror: { value: mirror },
        uIntensity: intensity,
        uCore: core,
      },
      { depthTest: !mirror },
    );
    effectMaterials.push(layerMaterial);
    const mesh = new THREE.Mesh(geometry, layerMaterial);
    mesh.frustumCulled = false;
    mesh.renderOrder = order;
    if (!mirror) mesh.layers.enable(1);
    scene.add(mesh);
    return { intensity, core };
  };

  const streakGroup = (
    direction: number,
    fade: [number, number],
    speedRange: [number, number],
  ) => {
    const geometry = instanced(tube);
    const seedA = new Float32Array(MAX_CARS * 2 * 4);
    const seedB = new Float32Array(MAX_CARS * 2 * 4);
    const pair = new Float32Array(MAX_CARS * 2);
    const tone = new Float32Array(MAX_CARS * 2);
    for (let i = 0; i < MAX_CARS; i++) {
      const a = [Math.random(), Math.random(), Math.random(), Math.random()];
      const b = [
        Math.random(),
        Math.random(),
        Math.random(),
        Math.random() * Math.random(),
      ];
      const shade = Math.random();
      for (let side = 0; side < 2; side++) {
        const index = i * 2 + side;
        seedA.set(a, index * 4);
        seedB.set(b, index * 4);
        pair[index] = side ? 0.5 : -0.5;
        tone[index] = shade;
      }
    }
    geometry.setAttribute(
      'aSeedA',
      new THREE.InstancedBufferAttribute(seedA, 4),
    );
    geometry.setAttribute(
      'aSeedB',
      new THREE.InstancedBufferAttribute(seedB, 4),
    );
    geometry.setAttribute('aPair', new THREE.InstancedBufferAttribute(pair, 1));
    geometry.setAttribute('aTone', new THREE.InstancedBufferAttribute(tone, 1));
    geometry.instanceCount = 0;
    disposables.push(geometry);
    const uniforms = {
      uRoadX: { value: 0 },
      uRoadWidth: { value: 10 },
      uLanes: { value: 3 },
      uDirection: { value: direction },
      uSpeedRange: { value: new THREE.Vector2(speedRange[0], speedRange[1]) },
      uTrail: { value: 1 },
      uSize: { value: 1 },
      uColors: swatches(),
      uColorCount: { value: 1 },
      uFade: { value: new THREE.Vector2(fade[0], fade[1]) },
    };
    return {
      geometry,
      uniforms,
      reflection: glowLayer(
        STREAK_VERTEX,
        STREAK_FRAGMENT,
        geometry,
        uniforms,
        2.1,
        1.2,
        1,
        1,
      ),
      core: glowLayer(
        STREAK_VERTEX,
        STREAK_FRAGMENT,
        geometry,
        uniforms,
        1,
        0.85,
        0,
        3,
      ),
    };
  };

  const tail = streakGroup(1, [0, 0.6], [60, 80]);
  const head = streakGroup(-1, [1, 0.4], [120, 160]);

  const cylinder = new THREE.CylinderGeometry(1, 1, 1, 8, 1, true);
  disposables.push(cylinder);
  const poleGeometry = instanced(cylinder);
  const poleSeed = new Float32Array(MAX_POLES * 2 * 4);
  const poleIndex = new Float32Array(MAX_POLES * 2);
  const poleSide = new Float32Array(MAX_POLES * 2);
  for (let i = 0; i < MAX_POLES; i++) {
    for (let side = 0; side < 2; side++) {
      const index = i * 2 + side;
      poleSeed.set(
        [Math.random(), Math.random(), Math.random(), Math.random()],
        index * 4,
      );
      poleIndex[index] = i + (side ? 0.5 : 0);
      poleSide[index] = side ? 1 : -1;
    }
  }
  poleGeometry.setAttribute(
    'aSeed',
    new THREE.InstancedBufferAttribute(poleSeed, 4),
  );
  poleGeometry.setAttribute(
    'aIndex',
    new THREE.InstancedBufferAttribute(poleIndex, 1),
  );
  poleGeometry.setAttribute(
    'aSide',
    new THREE.InstancedBufferAttribute(poleSide, 1),
  );
  poleGeometry.instanceCount = 0;
  disposables.push(poleGeometry);
  const poleUniforms = {
    uCount: { value: 20 },
    uEdge: { value: 11 },
    uHeight: { value: 1 },
    uColors: swatches(),
    uColorCount: { value: 1 },
  };
  const polesLayers = {
    reflection: glowLayer(
      POLE_VERTEX,
      POLE_FRAGMENT,
      poleGeometry,
      poleUniforms,
      2.4,
      1.2,
      1,
      1,
    ),
    core: glowLayer(
      POLE_VERTEX,
      POLE_FRAGMENT,
      poleGeometry,
      poleUniforms,
      1,
      0.8,
      0,
      3,
    ),
  };

  const dustGeometry = new THREE.BufferGeometry();
  const dustSeed = new Float32Array(MAX_DUST * 2 * 4);
  const dustEnd = new Float32Array(MAX_DUST * 2);
  for (let i = 0; i < MAX_DUST; i++) {
    const seed = [Math.random(), Math.random(), Math.random(), Math.random()];
    dustSeed.set(seed, i * 8);
    dustSeed.set(seed, i * 8 + 4);
    dustEnd[i * 2 + 1] = 1;
  }
  dustGeometry.setAttribute(
    'position',
    new THREE.BufferAttribute(new Float32Array(MAX_DUST * 2 * 3), 3),
  );
  dustGeometry.setAttribute('aSeed', new THREE.BufferAttribute(dustSeed, 4));
  dustGeometry.setAttribute('aEnd', new THREE.BufferAttribute(dustEnd, 1));
  dustGeometry.setDrawRange(0, 0);
  disposables.push(dustGeometry);
  const dustUniforms = {
    uSpread: { value: 140 },
    uColor: { value: new THREE.Vector3(1, 1, 1) },
    uIntensity: { value: 0.5 },
  };
  const dustMaterial = material(DUST_VERTEX, DUST_FRAGMENT, dustUniforms);
  effectMaterials.push(dustMaterial);
  const dustLines = new THREE.LineSegments(dustGeometry, dustMaterial);
  dustLines.frustumCulled = false;
  dustLines.renderOrder = 4;
  scene.add(dustLines);

  const floatTargets =
    renderer.extensions.has('EXT_color_buffer_float') ||
    renderer.extensions.has('EXT_color_buffer_half_float');
  const levels = Array.from({ length: 5 }, (_, index) => {
    const target = new THREE.WebGLRenderTarget(1, 1, {
      type: floatTargets ? THREE.HalfFloatType : THREE.UnsignedByteType,
      depthBuffer: index === 0,
    });
    disposables.push(target);
    return target;
  });
  const quadScene = new THREE.Scene();
  const quadCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const quadGeometry = new THREE.PlaneGeometry(2, 2);
  disposables.push(quadGeometry);
  const quad = new THREE.Mesh(quadGeometry);
  quad.frustumCulled = false;
  quadScene.add(quad);

  const blur = (fragmentShader: string, options: ShaderMaterialParameters) => {
    const uTexture: IUniform<THREE.Texture | null> = { value: null };
    const uniforms = {
      uTexture,
      uTexel: { value: new THREE.Vector2() },
      uStrength: { value: 1 },
      uCeiling: { value: 1 },
      uLight: { value: 0 },
    };
    const created = new THREE.ShaderMaterial({
      vertexShader: QUAD_VERTEX,
      fragmentShader,
      uniforms,
      depthTest: false,
      depthWrite: false,
      ...options,
    });
    disposables.push(created);
    return { material: created, uniforms };
  };
  const down = blur(DOWN_FRAGMENT, { blending: THREE.NoBlending });
  const up = blur(UP_FRAGMENT, {
    blending: THREE.CustomBlending,
    blendSrc: THREE.OneFactor,
    blendDst: THREE.OneFactor,
    blendSrcAlpha: THREE.OneFactor,
    blendDstAlpha: THREE.OneFactor,
  });
  const bloom = blur(BLOOM_FRAGMENT, {
    blending: THREE.CustomBlending,
    blendSrc: THREE.OneFactor,
  });
  const pass = (
    step: ReturnType<typeof blur>,
    source: THREE.WebGLRenderTarget,
    target: THREE.WebGLRenderTarget | null,
  ) => {
    quad.material = step.material;
    step.uniforms.uTexture.value = source.texture;
    step.uniforms.uTexel.value.set(1 / source.width, 1 / source.height);
    renderer.setRenderTarget(target);
    renderer.render(quadScene, quadCamera);
  };
  const clearColor = new THREE.Color();
  let clearAlpha = 0;

  const state = {
    boost: 0,
    held: false,
    fov: getSettings().fov,
    fovVelocity: 0,
    steerX: 0,
    steerY: 0,
    pointerX: 0,
    pointerY: 0,
    weights: [0, 0, 0, 0, 0],
    visible: true,
  };
  const keys = {
    tail: '',
    head: '',
    poles: '',
    surface: '',
  };
  let lastLight: boolean | null = null;
  const lookTarget = new THREE.Vector3();
  let raf = 0;
  let last = performance.now();
  let alive = true;

  const syncColors = (s: HyperspeedSettings) => {
    const tailKey = s.tailColors.join();
    if (tailKey !== keys.tail) {
      keys.tail = tailKey;
      fillPalette(
        tail.uniforms.uColors,
        tail.uniforms.uColorCount,
        s.tailColors,
      );
    }
    const headKey = s.headColors.join();
    if (headKey !== keys.head) {
      keys.head = headKey;
      fillPalette(
        head.uniforms.uColors,
        head.uniforms.uColorCount,
        s.headColors,
      );
    }
    const poleKey = s.poleColors.join();
    if (poleKey !== keys.poles) {
      keys.poles = poleKey;
      fillPalette(poleUniforms.uColors, poleUniforms.uColorCount, s.poleColors);
    }
    const surfaceKey = [
      s.roadColor,
      s.lineColor,
      s.background,
      s.dustColor,
    ].join();
    if (surfaceKey !== keys.surface) {
      keys.surface = surfaceKey;
      roadUniforms.uRoadColor.value.fromArray(toRgb(s.roadColor));
      roadUniforms.uLineColor.value.fromArray(toRgb(s.lineColor));
      dustUniforms.uColor.value.fromArray(toRgb(s.dustColor));
      const transparent = s.background === 'transparent';
      const backdrop: HyperspeedVec3 = transparent
        ? [0, 0, 0]
        : toRgb(s.background);
      roadUniforms.uBackground.value.fromArray(backdrop);
      roadUniforms.uTransparent.value = transparent ? 1 : 0;
      clearColor.setRGB(
        backdrop[0],
        backdrop[1],
        backdrop[2],
        THREE.LinearSRGBColorSpace,
      );
      clearAlpha = transparent ? 0 : 1;
    }
    if (lastLight !== s.light) {
      lastLight = s.light;
      for (const item of effectMaterials) {
        item.blending = s.light ? THREE.NormalBlending : THREE.AdditiveBlending;
        item.needsUpdate = true;
      }
      bloom.material.blendDst = s.light
        ? THREE.OneMinusSrcAlphaFactor
        : THREE.OneFactor;
      bloom.material.blendSrcAlpha = s.light
        ? THREE.OneFactor
        : THREE.ZeroFactor;
      bloom.material.blendDstAlpha = s.light
        ? THREE.OneMinusSrcAlphaFactor
        : THREE.OneFactor;
      bloom.uniforms.uLight.value = s.light ? 1 : 0;
    }
  };

  const frame = (now: number) => {
    raf = 0;
    if (!alive) return;
    const s = getSettings();
    const reduce = reducedMotion();
    const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000));
    last = now;
    syncColors(s);

    const wanted = (state.held && s.interactive) || s.boosting ? 1 : 0;
    state.boost +=
      (wanted - state.boost) *
      (1 - Math.exp(-dt / (wanted > state.boost ? 0.28 : 0.85)));
    const pace =
      s.speed * (reduce ? 0.3 : 1) * (1 + (s.boost - 1) * state.boost);
    shared.uTime.value += dt * pace;
    shared.uStretch.value = state.boost * 1.1;
    shared.uCurvature.value = s.curvature;

    const target = CURVES.indexOf(s.curve) - 1;
    const blend = 1 - Math.exp(-dt / 0.6);
    state.weights = state.weights.map(
      (weight, index) => weight + ((index === target ? 1 : 0) - weight) * blend,
    );
    const w = state.weights;
    shared.uCurveA.value.set(w[0]!, w[1]!, w[2]!, w[3]!);
    shared.uCurveB.value = w[4]!;

    const halfRoad = s.roadWidth / 2 + s.medianWidth / 2;
    const surface = 0.45 + 0.55 * s.roadOpacity;
    for (const [index, group] of [tail, head].entries()) {
      group.geometry.instanceCount = s.density * 2;
      group.uniforms.uRoadX.value = index ? halfRoad : -halfRoad;
      group.uniforms.uRoadWidth.value = s.roadWidth;
      group.uniforms.uLanes.value = s.lanes;
      group.uniforms.uTrail.value = s.trailLength;
      group.uniforms.uSize.value = s.lightSize;
      group.core.intensity.value = s.light ? 0.95 : 1 + 0.35 * state.boost;
      group.core.core.value = s.light ? 0 : 0.75;
      group.reflection.intensity.value =
        s.reflections * (s.light ? 0.22 : 0.42) * surface;
    }

    poleGeometry.instanceCount = s.poles * 2;
    poleUniforms.uCount.value = Math.max(1, s.poles);
    poleUniforms.uEdge.value = s.roadWidth + s.medianWidth / 2 + 0.8;
    poleUniforms.uHeight.value = s.poleHeight;
    polesLayers.core.intensity.value = s.light ? 0.9 : 1;
    polesLayers.core.core.value = s.light ? 0 : 0.6;
    polesLayers.reflection.intensity.value =
      s.reflections * (s.light ? 0.2 : 0.38) * surface;

    dustGeometry.setDrawRange(0, s.dust * 2);
    dustUniforms.uIntensity.value = (s.light ? 0.35 : 0.45) * (1 + state.boost);
    dustUniforms.uSpread.value = (s.roadWidth * 2 + s.medianWidth) * 5;

    roadUniforms.uWidth.value = s.roadWidth * 2 + s.medianWidth + 3;
    roadUniforms.uRoadWidth.value = s.roadWidth;
    roadUniforms.uMedian.value = s.medianWidth;
    roadUniforms.uLanes.value = s.lanes;
    roadUniforms.uOpacity.value = s.roadOpacity;
    roadMaterial.depthWrite = s.roadOpacity > 0.5;

    const fovTarget = reduce
      ? s.fov
      : s.fov + (s.boostFov - s.fov) * state.boost;
    state.fovVelocity +=
      ((fovTarget - state.fov) * 90 - state.fovVelocity * 13) * dt;
    state.fov += state.fovVelocity * dt;
    camera.fov = state.fov;
    shared.uPixel.value =
      (2 * Math.tan((state.fov * Math.PI) / 360)) /
      Math.max(1, renderer.domElement.height);

    const steerBlend = 1 - Math.exp(-dt / 0.35);
    const follow = s.interactive ? s.steer : 0;
    state.steerX += (state.pointerX * follow - state.steerX) * steerBlend;
    state.steerY += (state.pointerY * follow - state.steerY) * steerBlend;
    camera.position.set(
      state.steerX * s.roadWidth * 0.45,
      8 - state.steerY * 2.5,
      -5,
    );

    const looks = lookShapes(shared.uTime.value, s.curvature);
    const straight = 1 - w.reduce((sum, weight) => sum + weight, 0);
    lookTarget.set(0, 0, -10 * straight);
    for (const [index, look] of looks.entries()) {
      const weight = w[index]!;
      lookTarget.x += look[0] * weight;
      lookTarget.y += look[1] * weight;
      lookTarget.z += look[2] * weight;
    }
    lookTarget.x += state.steerX * 2.5;
    lookTarget.add(camera.position);
    camera.lookAt(lookTarget);
    camera.updateProjectionMatrix();

    renderer.setRenderTarget(null);
    renderer.setClearColor(clearColor, clearAlpha);
    renderer.clear();
    renderer.render(scene, camera);

    if (s.glow > 0) {
      const first = levels[0]!;
      const pixel = shared.uPixel.value;
      shared.uPixel.value = pixel * (renderer.domElement.height / first.height);
      camera.layers.set(1);
      roadMaterial.colorWrite = false;
      renderer.setRenderTarget(first);
      renderer.setClearColor(0x000000, 0);
      renderer.clear();
      renderer.render(scene, camera);
      roadMaterial.colorWrite = true;
      camera.layers.set(0);
      shared.uPixel.value = pixel;
      for (let i = 1; i < levels.length; i++) {
        pass(down, levels[i - 1]!, levels[i]!);
      }
      for (let i = levels.length - 1; i > 1; i--) {
        pass(up, levels[i]!, levels[i - 1]!);
      }
      bloom.uniforms.uStrength.value = s.glow * (s.light ? 0.5 : 1.4);
      bloom.uniforms.uCeiling.value = s.glow * (s.light ? 0.3 : 0.5);
      pass(bloom, levels[1]!, null);
    }

    if (state.visible) raf = requestAnimationFrame(frame);
  };

  const wake = () => {
    if (raf || !alive || !state.visible) return;
    last = performance.now();
    raf = requestAnimationFrame(frame);
  };

  const resize = () => {
    const width = Math.max(1, container.clientWidth);
    const height = Math.max(1, container.clientHeight);
    renderer.setSize(width, height, false);
    for (const [index, target] of levels.entries()) {
      target.setSize(
        Math.max(1, Math.round(width / 2 ** (index + 1))),
        Math.max(1, Math.round(height / 2 ** (index + 1))),
      );
    }
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    wake();
  };

  resize();

  return {
    resize,
    setVisible(visible) {
      state.visible = visible;
      if (visible) wake();
    },
    setHeld(held) {
      state.held = held;
    },
    setPointer(x, y) {
      state.pointerX = x;
      state.pointerY = y;
    },
    dispose() {
      alive = false;
      cancelAnimationFrame(raf);
      for (const item of disposables) item.dispose();
      renderer.dispose();
      renderer.forceContextLoss();
      renderer.domElement.remove();
    },
  };
}

import { MAX_COLORS } from './hyperspeed-config';

const BEND = /* glsl */ `
  uniform float uTime;
  uniform float uCurvature;
  uniform vec4 uCurveA;
  uniform float uCurveB;
  uniform float uFogNear;
  uniform float uFogFar;
  uniform float uPixel;
  #define PI 3.14159265358979
  float nsin(float v) { return sin(v) * 0.5 + 0.5; }
  vec3 gentle(float p) {
    return vec3(
      cos(p * PI * 5.0 + uTime) * 25.0 - cos(0.02 * PI * 5.0 + uTime) * 25.0,
      sin(p * PI * 2.0 + PI * 0.5 + uTime) * 15.0 - sin(0.02 * PI * 2.0 + PI * 0.5 + uTime) * 15.0,
      0.0
    );
  }
  float windX(float p) { return cos(PI * p * 4.0 + uTime) * 25.0 + pow(cos(PI * p * 8.0 + uTime * 2.0), 2.0) * 5.0; }
  float windY(float p) { return -nsin(PI * p * 8.0 + uTime) * 10.0 - pow(nsin(PI * p + uTime / 8.0), 5.0) * 10.0; }
  vec3 winding(float p) { return vec3(windX(p) - windX(0.0125), windY(p) - windY(0.0125), 0.0); }
  vec3 hills(float p) {
    return vec3(
      cos(p * PI * 3.0 + uTime) * 30.0 - cos(0.02 * PI * 3.0 + uTime) * 30.0,
      nsin(p * PI * 6.0 + uTime) * 30.0 - nsin(0.02 * PI * 6.0 + uTime) * 30.0,
      nsin(p * PI * 10.0 + uTime) * 20.0 - nsin(0.02 * PI * 10.0 + uTime) * 20.0
    );
  }
  vec3 racing(float p) {
    return vec3(
      sin(p * PI * 2.0 + uTime) * 35.0 - sin(0.0125 * PI * 2.0 + uTime) * 35.0,
      sin(p * PI * 3.0 + uTime) * 10.0 - sin(0.0125 * PI * 3.0 + uTime) * 10.0,
      0.0
    );
  }
  float deepX(float p) { return sin(p * PI * 4.0 + uTime) * 10.0; }
  float deepY(float p) { return pow(abs(p * 10.0), 2.0) + sin(p * PI * 8.0 + uTime) * 20.0; }
  vec3 deep(float p) { return vec3(deepX(p) - deepX(0.02), deepY(p) - deepY(0.02), 0.0); }
  vec3 bend(float p) {
    vec3 d = gentle(p) * uCurveA.x + winding(p) * uCurveA.y + hills(p) * uCurveA.z + racing(p) * uCurveA.w + deep(p) * uCurveB;
    return d * uCurvature;
  }
`;

export const STREAK_VERTEX = /* glsl */ `
  ${BEND}
  attribute vec4 aSeedA;
  attribute vec4 aSeedB;
  attribute float aPair;
  attribute float aTone;
  uniform float uTravel;
  uniform float uRoadX;
  uniform float uRoadWidth;
  uniform float uLanes;
  uniform float uDirection;
  uniform vec2 uSpeedRange;
  uniform float uTrail;
  uniform float uStretch;
  uniform float uSize;
  uniform float uRadiusScale;
  uniform float uMirror;
  uniform vec3 uColors[${MAX_COLORS}];
  uniform float uColorCount;
  varying vec2 vUv;
  varying vec3 vNormal;
  varying vec3 vView;
  varying vec3 vColor;
  varying float vFog;
  varying float vAbove;
  varying float vThin;
  void main() {
    float laneWidth = uRoadWidth / uLanes;
    float lane = min(floor(aSeedA.x * uLanes), uLanes - 1.0);
    float laneX = (lane + 0.5) * laneWidth - uRoadWidth * 0.5 + (aSeedA.y - 0.5) * 0.5 * laneWidth;
    float carWidth = mix(0.3, 0.5, aSeedA.z) * laneWidth;
    float radius = mix(0.05, 0.14, aSeedA.w) * uSize;
    float len = mix(0.03, 0.2, aSeedB.x) * uTravel * uTrail * (1.0 + uStretch);
    float speed = mix(uSpeedRange.x, uSpeedRange.y, aSeedB.y) * uDirection;
    vec3 center = vec3(
      uRoadX + laneX + aPair * carWidth,
      aSeedB.w * 0.8 + radius * 1.3,
      position.z * len + len - mod(uTime * speed + aSeedB.z * uTravel, uTravel)
    );
    vAbove = center.y;
    center.y = mix(center.y, -center.y * 1.8, uMirror);
    center += bend(abs(center.z / uTravel));
    float depth = max(0.1, -(modelViewMatrix * vec4(center, 1.0)).z);
    float wanted = radius * uRadiusScale;
    float shown = max(wanted, depth * uPixel * 0.75);
    vThin = wanted / shown;
    vec3 p = center + vec3(position.x * shown, position.y * shown * mix(1.0, 2.2, uMirror), 0.0);
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    gl_Position = projectionMatrix * mv;
    vec3 n = normal;
    n.y *= 1.0 - 2.0 * uMirror;
    vNormal = normalize(normalMatrix * n);
    vView = -mv.xyz;
    vUv = uv;
    vColor = uColors[int(min(floor(aTone * uColorCount), uColorCount - 1.0))];
    vFog = smoothstep(uFogNear, uFogFar, -mv.z);
  }
`;

export const STREAK_FRAGMENT = /* glsl */ `
  uniform vec2 uFade;
  uniform float uIntensity;
  uniform float uSharp;
  uniform float uCore;
  uniform float uMirror;
  varying vec2 vUv;
  varying vec3 vNormal;
  varying vec3 vView;
  varying vec3 vColor;
  varying float vFog;
  varying float vAbove;
  varying float vThin;
  void main() {
    float facing = abs(dot(normalize(vNormal), normalize(vView)));
    float alpha = pow(facing, uSharp) * smoothstep(uFade.x, uFade.y, vUv.x) * uIntensity * vThin * (1.0 - vFog);
    alpha *= mix(1.0, exp(-vAbove * 0.9), uMirror);
    if (alpha < 0.003) discard;
    gl_FragColor = vec4(mix(vColor, vec3(1.0), pow(facing, 12.0) * uCore), min(alpha, 1.0));
  }
`;

export const POLE_VERTEX = /* glsl */ `
  ${BEND}
  attribute vec4 aSeed;
  attribute float aIndex;
  attribute float aSide;
  uniform float uTravel;
  uniform float uCount;
  uniform float uEdge;
  uniform float uHeight;
  uniform float uRadiusScale;
  uniform float uMirror;
  uniform vec3 uColors[${MAX_COLORS}];
  uniform float uColorCount;
  varying vec3 vNormal;
  varying vec3 vView;
  varying vec3 vColor;
  varying float vFog;
  varying float vAbove;
  varying float vHeight;
  varying float vThin;
  void main() {
    vHeight = position.y + 0.5;
    float width = mix(0.08, 0.22, aSeed.y);
    float height = mix(1.3, 1.9, aSeed.z) * uHeight;
    float spacing = uTravel / max(uCount, 1.0);
    vec3 center = vec3(
      aSide * uEdge,
      vHeight * height,
      -uTravel + mod(uTime * 120.0 + (aIndex + aSeed.x * 0.6) * spacing, uTravel)
    );
    vAbove = center.y;
    center.y = mix(center.y, -center.y * 1.6, uMirror);
    center += bend(abs(center.z / uTravel));
    float depth = max(0.1, -(modelViewMatrix * vec4(center, 1.0)).z);
    float wanted = width * uRadiusScale;
    float shown = max(wanted, depth * uPixel * 0.75);
    vThin = wanted / shown;
    vec3 p = center + vec3(position.x * shown, 0.0, position.z * shown);
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    gl_Position = projectionMatrix * mv;
    vNormal = normalize(normalMatrix * normal);
    vView = -mv.xyz;
    vColor = uColors[int(min(floor(aSeed.w * uColorCount), uColorCount - 1.0))];
    vFog = smoothstep(uFogNear, uFogFar, -mv.z);
  }
`;

export const POLE_FRAGMENT = /* glsl */ `
  uniform float uIntensity;
  uniform float uSharp;
  uniform float uCore;
  uniform float uMirror;
  varying vec3 vNormal;
  varying vec3 vView;
  varying vec3 vColor;
  varying float vFog;
  varying float vAbove;
  varying float vHeight;
  varying float vThin;
  void main() {
    float facing = abs(dot(normalize(vNormal), normalize(vView)));
    float ends = smoothstep(0.0, 0.08, vHeight) * smoothstep(1.0, 0.9, vHeight);
    float alpha = pow(facing, uSharp) * ends * uIntensity * vThin * (1.0 - vFog);
    alpha *= mix(1.0, exp(-vAbove * 0.6), uMirror);
    if (alpha < 0.003) discard;
    gl_FragColor = vec4(mix(vColor, vec3(1.0), pow(facing, 12.0) * uCore), min(alpha, 1.0));
  }
`;

export const DUST_VERTEX = /* glsl */ `
  ${BEND}
  attribute vec4 aSeed;
  attribute float aEnd;
  uniform float uTravel;
  uniform float uStretch;
  uniform float uSpread;
  varying float vAlpha;
  void main() {
    float x = (aSeed.x - 0.5) * uSpread;
    float y = mix(1.0, 42.0, aSeed.y * aSeed.y);
    float speed = mix(140.0, 260.0, aSeed.w);
    float z = -uTravel + mod(uTime * speed + aSeed.z * uTravel, uTravel);
    float len = (0.6 + uStretch * 7.0) * mix(0.6, 1.4, aSeed.w);
    vec3 p = vec3(x, y, z + aEnd * len);
    p += bend(abs(p.z / uTravel));
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    gl_Position = projectionMatrix * mv;
    vAlpha = aEnd * (1.0 - smoothstep(uFogNear, uFogFar, -mv.z));
  }
`;

export const DUST_FRAGMENT = /* glsl */ `
  uniform vec3 uColor;
  uniform float uIntensity;
  varying float vAlpha;
  void main() {
    gl_FragColor = vec4(uColor, vAlpha * uIntensity);
  }
`;

export const ROAD_VERTEX = /* glsl */ `
  ${BEND}
  uniform float uTravel;
  uniform float uWidth;
  varying vec2 vRoad;
  varying float vFog;
  void main() {
    vec3 p = position;
    p.x *= uWidth;
    vRoad = vec2(p.x, p.z);
    p += bend(abs(p.z / uTravel));
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    gl_Position = projectionMatrix * mv;
    vFog = smoothstep(uFogNear, uFogFar, -mv.z);
  }
`;

export const ROAD_FRAGMENT = /* glsl */ `
  uniform float uTime;
  uniform vec3 uRoadColor;
  uniform vec3 uLineColor;
  uniform vec3 uBackground;
  uniform float uRoadWidth;
  uniform float uMedian;
  uniform float uLanes;
  uniform float uTransparent;
  uniform float uOpacity;
  varying vec2 vRoad;
  varying float vFog;
  float stripe(float d, float w) {
    float aa = fwidth(d) * 1.2;
    return 1.0 - smoothstep(w - aa, w + aa, d);
  }
  void main() {
    float rx = abs(vRoad.x) - uMedian * 0.5;
    vec3 color = rx < 0.0 ? mix(uRoadColor, uLineColor, 0.12) : uRoadColor;
    if (rx >= 0.0) {
      float laneWidth = uRoadWidth / uLanes;
      float shoulder = max(stripe(abs(rx - 0.3), 0.07), stripe(abs(rx - (uRoadWidth - 0.3)), 0.07));
      float nearest = floor(rx / laneWidth + 0.5);
      float inner = step(0.5, nearest) * step(nearest, uLanes - 0.5);
      float dash = step(0.5, fract((vRoad.y - uTime * 120.0) / 14.0));
      float marks = max(shoulder, stripe(abs(rx - nearest * laneWidth), 0.06) * inner * dash);
      color = mix(color, uLineColor, marks);
    }
    float alpha = mix(1.0, 1.0 - vFog, uTransparent) * uOpacity;
    gl_FragColor = vec4(mix(color, uBackground, vFog * (1.0 - uTransparent)), alpha);
  }
`;

export const QUAD_VERTEX = /* glsl */ `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = vec4(position.xy, 0.0, 1.0);
  }
`;

export const DOWN_FRAGMENT = /* glsl */ `
  uniform sampler2D uTexture;
  uniform vec2 uTexel;
  varying vec2 vUv;
  vec4 tap(vec2 offset) {
    return min(texture2D(uTexture, vUv + uTexel * offset), vec4(1.0));
  }
  void main() {
    vec4 sum = tap(vec2(0.0)) * 4.0 + tap(vec2(-1.0, -1.0)) + tap(vec2(1.0, -1.0)) + tap(vec2(-1.0, 1.0)) + tap(vec2(1.0, 1.0));
    gl_FragColor = sum * 0.125;
  }
`;

const TENT = /* glsl */ `
  uniform sampler2D uTexture;
  uniform vec2 uTexel;
  varying vec2 vUv;
  vec4 tent() {
    vec4 sum = texture2D(uTexture, vUv + uTexel * vec2(-1.0, 0.0));
    sum += texture2D(uTexture, vUv + uTexel * vec2(1.0, 0.0));
    sum += texture2D(uTexture, vUv + uTexel * vec2(0.0, -1.0));
    sum += texture2D(uTexture, vUv + uTexel * vec2(0.0, 1.0));
    sum += texture2D(uTexture, vUv + uTexel * vec2(-0.5, -0.5)) * 2.0;
    sum += texture2D(uTexture, vUv + uTexel * vec2(0.5, -0.5)) * 2.0;
    sum += texture2D(uTexture, vUv + uTexel * vec2(-0.5, 0.5)) * 2.0;
    sum += texture2D(uTexture, vUv + uTexel * vec2(0.5, 0.5)) * 2.0;
    return sum / 12.0;
  }
`;

export const UP_FRAGMENT = /* glsl */ `
  ${TENT}
  void main() {
    gl_FragColor = tent();
  }
`;

export const BLOOM_FRAGMENT = /* glsl */ `
  ${TENT}
  uniform float uStrength;
  uniform float uCeiling;
  uniform float uLight;
  void main() {
    vec4 color = tent() * uStrength;
    float peak = max(uLight > 0.5 ? color.a : max(color.r, max(color.g, color.b)), 0.0001);
    color *= uCeiling * (1.0 - exp(-peak / uCeiling)) / peak;
    gl_FragColor = uLight > 0.5 ? color : vec4(color.rgb, 0.0);
  }
`;

export { default as Hyperspeed } from './Hyperspeed.vue';
export type {
  HyperspeedCurve,
  HyperspeedProps,
  HyperspeedTheme,
} from './types';

export type HyperspeedCurve =
  | 'straight'
  | 'gentle'
  | 'winding'
  | 'hills'
  | 'racing'
  | 'deep';

export type HyperspeedTheme = 'dark' | 'light';

export type HyperspeedVec3 = [number, number, number];

export interface HyperspeedProps {
  /** Shape of the road. Switching between curves morphs the road smoothly. */
  curve?: HyperspeedCurve;
  /** How strongly the road bends. 0 is straight. */
  curvature?: number;
  /** Cruising speed of the traffic, poles and road markings. */
  speed?: number;
  /** Speed multiplier while the pointer is held down. */
  boost?: number;
  /** Camera field of view in degrees. */
  fov?: number;
  /** Field of view while boosting. */
  boostFov?: number;
  /** Lanes on each side of the road. */
  lanes?: number;
  /** Width of each side of the road. */
  roadWidth?: number;
  /** Width of the strip between the two sides. */
  medianWidth?: number;
  /** Cars on each side of the road, up to 160. */
  density?: number;
  /** Length of the light trails. */
  trailLength?: number;
  /** Thickness of the light trails. */
  lightSize?: number;
  /** Light poles on each shoulder, up to 80. 0 removes them. */
  poles?: number;
  /** Height of the light poles. */
  poleHeight?: number;
  /** Speed streaks flying past in the air, up to 1500. */
  dust?: number;
  /** Soft bloom around every light. 0 turns it off. */
  glow?: number;
  /** How much the lights reflect on the road. */
  reflections?: number;
  /** How far the camera drifts and turns toward the pointer. */
  steer?: number;
  /** Colors of the lights moving away on the left road. */
  tailColors?: string[];
  /** Colors of the oncoming lights on the right road. */
  headColors?: string[];
  /** Colors of the light poles along both shoulders. */
  poleColors?: string[];
  /** Color of the asphalt. Follows the theme when not set. */
  roadColor?: string;
  /** Opacity of the road and its markings. */
  roadOpacity?: number;
  /** Color of the lane markings. Follows the theme when not set. */
  lineColor?: string;
  /** Color behind the road. Unset keeps the canvas transparent. */
  background?: string;
  /** Dark renders glowing trails, light renders crisp trails on a pale road. */
  theme?: HyperspeedTheme;
  /** Click and hold to boost, and let the camera follow the pointer. */
  interactive?: boolean;
  /** Turns the boost on from your own code. */
  boosting?: boolean;
  class?: string;
}

export interface HyperspeedPalette {
  background: string;
  road: string;
  lines: string;
  tail: string[];
  head: string[];
  poles: string[];
  dust: string;
}

export interface HyperspeedSettings {
  light: boolean;
  curve: HyperspeedCurve;
  curvature: number;
  speed: number;
  boost: number;
  fov: number;
  boostFov: number;
  lanes: number;
  roadWidth: number;
  medianWidth: number;
  density: number;
  trailLength: number;
  lightSize: number;
  poles: number;
  poleHeight: number;
  dust: number;
  glow: number;
  reflections: number;
  steer: number;
  tailColors: string[];
  headColors: string[];
  poleColors: string[];
  roadColor: string;
  roadOpacity: number;
  lineColor: string;
  background: string;
  dustColor: string;
  interactive: boolean;
  boosting: boolean;
}

export interface HyperspeedEngine {
  resize: () => void;
